app.controller('GreetingController', ['$scope', function($scope) {
    $scope.greeting = 'Welcome to AngularJS';
    $scope.sayHello = function() {
        alert($scope.greeting);
    };
}]);

app.factory('ApiService', ['$http', function($http) {
    return {
        fetchData: function() {
            return $http.get('/api/data')
                .then(response => response.data)
                .catch(err => console.error(err));
        }
    };
}]);

// Factory pattern (most common)
app.factory('SharedState', function() {
    var value = 'shared';
    return {
        get: () => value,
        set: (v) => { value = v; }
    };
});

app.directive('conceptCard', function() {
    return {
        restrict: 'E',
        scope: {
            topic: '=topicData'
        },
        template: '<div class="card"><h4>{{ topic.title }}</h4></div>'
    };
});
